selector_to_html = {"a[href=\"#user-guide\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">User Guide<a class=\"headerlink\" href=\"#user-guide\" title=\"Link to this heading\">#</a></h1><p>This guide covers how to use FlagQuantum for quantum circuit simulation and\ntraining: building programs, planning and running them, training with PyTorch,\nchoosing a simulation representation, adding noise and measurement, scaling\nacross ranks, and moving the same program to hardware.</p>", "a[href=\"algorithms.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Algorithms, error correction and digital twins<a class=\"headerlink\" href=\"#algorithms-error-correction-and-digital-twins\" title=\"Link to this heading\">#</a></h1><h2>Algorithm units<a class=\"headerlink\" href=\"#algorithm-units\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">flagquantum.algorithms</span></code> composes user-facing algorithm units on top of the\nstable circuit and runtime API. They are exported from the subpackage surface\nrather than the <code class=\"docutils literal notranslate\"><span class=\"pre\">fq</span></code> alias.</p>", "a[href=\"run-tests.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Run tests<a class=\"headerlink\" href=\"#run-tests\" title=\"Link to this heading\">#</a></h1><p>Install the development dependencies, then run the smallest meaningful tier\nfirst and expand by blast radius.</p>", "a[href=\"training-with-pytorch.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Training with PyTorch<a class=\"headerlink\" href=\"#training-with-pytorch\" title=\"Link to this heading\">#</a></h1><p>Execution and training are intentionally separate. A trainable program is an\n<code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Module</span></code> inside an ordinary PyTorch training loop.</p>", "a[href=\"distributed-execution.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Distributed execution<a class=\"headerlink\" href=\"#distributed-execution\" title=\"Link to this heading\">#</a></h1><p>Distributed execution extends the same programming model to genuinely sharded\nworkloads. One logical workload is split across ranks; replicated execution is\nnever presented as capacity scaling.</p>", "a[href=\"measurement-and-noise.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Measurement and noise<a class=\"headerlink\" href=\"#measurement-and-noise\" title=\"Link to this heading\">#</a></h1><h2>Observables and outputs<a class=\"headerlink\" href=\"#observables-and-outputs\" title=\"Link to this heading\">#</a></h2><p>Describe mathematical observables with <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.X</span></code>, <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Y</span></code> and <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Z</span></code>, then request\nnamed outputs from <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.plan</span></code> or <code class=\"docutils literal notranslate\"><span class=\"pre\">fq.run</span></code>. Pauli products use <code class=\"docutils literal notranslate\"><span class=\"pre\">@</span></code>; Hamiltonian\nsums and real coefficients use ordinary arithmetic.</p>", "a[href=\"basic-usage.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Basic usage<a class=\"headerlink\" href=\"#basic-usage\" title=\"Link to this heading\">#</a></h1><p>Create a circuit, inspect its plan, execute it and read the result. This is the\nshortest complete journey through the stable API.</p>", "a[href=\"circuits-and-ir.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Circuits and FlagQuantum IR<a class=\"headerlink\" href=\"#circuits-and-flagquantum-ir\" title=\"Link to this heading\">#</a></h1><h2>Circuit construction<a class=\"headerlink\" href=\"#circuit-construction\" title=\"Link to this heading\">#</a></h2><p><code class=\"docutils literal notranslate\"><span class=\"pre\">fq.Circuit(n_qubits=...)</span></code> is the preferred public spelling for circuit size.\nPositional construction, <code class=\"docutils literal notranslate\"><span class=\"pre\">n_wires=</span></code> and the legacy <code class=\"docutils literal notranslate\"><span class=\"pre\">nqubits=</span></code> remain\ncompatible; conflicting aliases fail during construction. Runtime, compiler and\nIR internals continue to use <em>wire</em> for logical mappings.</p>", "a[href=\"hardware-and-remote.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Hardware and remote targets<a class=\"headerlink\" href=\"#hardware-and-remote-targets\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum runs the same program on locally controlled resources and on\nexternal execution destinations. The two are named differently on purpose:\n<code class=\"docutils literal notranslate\"><span class=\"pre\">ExecutionOptions</span></code> describes the current process\u2019s devices, while <code class=\"docutils literal notranslate\"><span class=\"pre\">target</span></code>\nnames an external system.</p>", "a[href=\"tutorials.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Tutorials<a class=\"headerlink\" href=\"#tutorials\" title=\"Link to this heading\">#</a></h1><p>The tutorial series teaches the concepts behind the runnable examples. Read the\nnotebooks in order as a new user, but each one also stands alone.</p>", "a[href=\"simulation-representations.html\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Simulation representations<a class=\"headerlink\" href=\"#simulation-representations\" title=\"Link to this heading\">#</a></h1><p>FlagQuantum exposes several simulation representations behind one program, so a\nmodel does not have to be rewritten when the workload changes.</p>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
